var t=`1283-goat-water`;var n=`world-1283`;var a=`KN`;var o=`central-america-caribbean`;var s=4;var r=155;var g={en:`Goat Water`,ua:`Суп із козлятини`};var d={en:`Goat Water is a dish from Saint Kitts and Nevis featuring goat shoulder, yellow onion, garlic, tomato. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Суп із козлятини, страва кухні країни Сент-Кіттс і Невіс з такими основними складниками: козяча лопатка, жовта цибуля, часник, помідор. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var l=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`goat-shoulder`,850,`g`],[`canola-oil`,40,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,165,`g`],[`garlic`,5,`clove`],[`tomato`,280,`g`],[`thyme`,4,`sprig`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 105 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 105 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:105,i:[[`water`,1500,`ml`],[`ground-allspice`,5,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 25 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 25 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:25,i:[[`yam`,320,`g`],[`carrot`,230,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,25,`g`]]}];var u={slug:t,id:n,country:`KN`,region:o,servings:4,minutes:155,title:g,text:d,steps:l};export{a as country,u as default,n as id,r as minutes,o as region,s as servings,t as slug,l as steps,d as text,g as title};